/* Comparateur actif / passif — érosion des frais */
(function () {
  var svg = document.getElementById("fd-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function activeLang(){ return document.body.getAttribute("data-active-lang") || "fr"; }
  function fmt(x){ var l=activeLang(); return Math.round(x).toLocaleString(l==="en"?"en-US":(l==="nl"?"nl-BE":"fr-FR"))+" €"; }

  function draw() {
    var N=v("fd-n"), g=v("fd-g"), a=v("fd-a"), fp=v("fd-fp"), fa=v("fd-fa");
    setT("fd-n-o", v("fd-n")); setT("fd-g-o", v("fd-g")+"%"); setT("fd-a-o", v("fd-a").toFixed(1)+"%");
    setT("fd-fp-o", v("fd-fp").toFixed(2)+"%"); setT("fd-fa-o", v("fd-fa").toFixed(2)+"%");

    var P0=10000;
    var rp=(g-fp)/100, ra=(g+a-fa)/100;
    var vp=P0*Math.pow(1+rp,N), va=P0*Math.pow(1+ra,N);
    setT("fd-vp", fmt(vp)); setT("fd-va", fmt(va));
    var gap=vp-va;
    setT("fd-gap", (gap>=0?"+":"−")+fmt(Math.abs(gap)).replace("-","")+" ("+(vp>0?((gap/vp)*100).toFixed(0):0)+"%)");

    var W=520,H=300,L=58,R=16,T=14,B=30, pw=W-L-R, ph=H-T-B;
    var ymax=Math.max(vp,va,P0)*1.08;
    function px(i){ return L + i/N*pw; }
    function py(y){ return T + (1 - y/ymax)*ph; }

    var gg="";
    for (var k=0;k<=4;k++){ var yv=ymax*k/4, Y=py(yv);
      gg+='<line class="grid" x1="'+L+'" y1="'+Y+'" x2="'+(L+pw)+'" y2="'+Y+'"/>';
      gg+='<text class="tick" x="'+(L-6)+'" y="'+(Y+3)+'" text-anchor="end">'+Math.round(yv/1000)+'k</text>';
    }
    var nx=Math.min(N,8);
    for (var m=0;m<=nx;m++){ var iv=Math.round(N*m/nx), X=px(iv);
      gg+='<text class="tick" x="'+X+'" y="'+(T+ph+13)+'" text-anchor="middle">'+iv+'</text>';
    }
    gg+='<line class="axis" x1="'+L+'" y1="'+(T+ph)+'" x2="'+(L+pw)+'" y2="'+(T+ph)+'"/>';
    gg+='<line class="axis" x1="'+L+'" y1="'+T+'" x2="'+L+'" y2="'+(T+ph)+'"/>';

    function path(rate){ var s=""; for (var i=0;i<=N;i++){ var y=P0*Math.pow(1+rate,i); s+=(i===0?"M":"L")+px(i).toFixed(1)+","+py(y).toFixed(1)+" "; } return s.trim(); }
    gg+='<path class="cp" d="'+path(rp)+'"/>';
    gg+='<path class="ca" d="'+path(ra)+'"/>';

    gg+='<text class="alab" x="'+(L+pw/2)+'" y="'+(H-2)+'" text-anchor="middle">'+(activeLang()==="en"?"years":(activeLang()==="nl"?"jaren":"années"))+'</text>';
    svg.innerHTML=gg;
  }

  ["fd-n","fd-g","fd-a","fd-fp","fd-fa"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
